/* ===== Popup ảnh khách hàng (dải ảnh chạy ngang) ===== */
(function () {
    var links = document.querySelectorAll('.custom-scroll-wrapper .kh-popup');
    if (!links.length) return;

    // each photo appears twice per track for the loop; the popup shows each one once
    var photos = [];
    links.forEach(function (a) {
        var i = +a.getAttribute('data-index');
        if (!photos[i]) photos[i] = a.getAttribute('href');
    });
    photos = photos.filter(Boolean);

    var box = document.createElement('div');
    box.className = 'kh-lightbox';
    box.innerHTML =
        '<button type="button" class="kh-lightbox__close" aria-label="Đóng">&times;</button>' +
        '<button type="button" class="kh-lightbox__nav kh-lightbox__prev" aria-label="Ảnh trước">&#8249;</button>' +
        '<img class="kh-lightbox__img" alt="Khách hàng Đệ Nhất Đỉnh">' +
        '<button type="button" class="kh-lightbox__nav kh-lightbox__next" aria-label="Ảnh sau">&#8250;</button>' +
        '<div class="kh-lightbox__count"></div>';
    document.body.appendChild(box);

    var img = box.querySelector('.kh-lightbox__img');
    var count = box.querySelector('.kh-lightbox__count');
    var wrapper = document.querySelector('.custom-scroll-wrapper');
    var current = 0;

    function show(i) {
        current = (i + photos.length) % photos.length;
        img.src = photos[current];
        count.textContent = (current + 1) + ' / ' + photos.length;
        // warm the next photo so arrow clicks feel instant
        new Image().src = photos[(current + 1) % photos.length];
    }
    function open(i) {
        show(i);
        box.classList.add('is-open');
        wrapper.classList.add('is-paused');
        document.documentElement.style.overflow = 'hidden';
    }
    function close() {
        box.classList.remove('is-open');
        wrapper.classList.remove('is-paused');
        document.documentElement.style.overflow = '';
    }

    links.forEach(function (a) {
        a.addEventListener('click', function (e) {
            e.preventDefault();
            open(+a.getAttribute('data-index'));
        });
    });
    box.querySelector('.kh-lightbox__close').addEventListener('click', close);
    box.querySelector('.kh-lightbox__prev').addEventListener('click', function () { show(current - 1); });
    box.querySelector('.kh-lightbox__next').addEventListener('click', function () { show(current + 1); });
    box.addEventListener('click', function (e) { if (e.target === box) close(); });
    document.addEventListener('keydown', function (e) {
        if (!box.classList.contains('is-open')) return;
        if (e.key === 'Escape') close();
        else if (e.key === 'ArrowLeft') show(current - 1);
        else if (e.key === 'ArrowRight') show(current + 1);
    });

    // swipe left/right on phones
    var startX = null;
    box.addEventListener('touchstart', function (e) { startX = e.touches[0].clientX; }, { passive: true });
    box.addEventListener('touchend', function (e) {
        if (startX === null) return;
        var dx = e.changedTouches[0].clientX - startX;
        if (Math.abs(dx) > 50) show(current + (dx < 0 ? 1 : -1));
        startX = null;
    });
})();

/* ===== Popup video (banner Nghệ sĩ Tự Long) ===== */
(function () {
    var openers = document.querySelectorAll('.dnd-video-open');
    if (!openers.length) return;
    var box = document.createElement('div');
    box.className = 'dnd-video-box';
    box.innerHTML = '<button type="button" class="dnd-video-box__close" aria-label="Đóng">&times;</button>' +
        '<video controls playsinline preload="none"></video>';
    document.body.appendChild(box);
    var video = box.querySelector('video');

    // the review slider must not keep rotating behind the video
    function slider() {
        var el = document.querySelector('.dnd-review-slider .slider');
        return el && window.jQuery ? jQuery(el).data('flickity') : null;
    }

    function open(src) {
        if (video.getAttribute('src') !== src) video.setAttribute('src', src);
        box.classList.add('is-open');
        document.documentElement.style.overflow = 'hidden';
        // stop, not pause: leaving the slider with the mouse would unpause it
        var f = slider();
        if (f) f.stopPlayer();
        var p = video.play();
        if (p && p.catch) p.catch(function () {});
    }
    function close() {
        video.pause();
        box.classList.remove('is-open');
        document.documentElement.style.overflow = '';
        var f = slider();
        if (f) f.playPlayer();
    }

    openers.forEach(function (a) {
        a.addEventListener('click', function (e) {
            e.preventDefault();
            e.stopPropagation();
            open(a.getAttribute('href'));
        });
    });
    box.querySelector('.dnd-video-box__close').addEventListener('click', close);
    box.addEventListener('click', function (e) { if (e.target === box) close(); });
    document.addEventListener('keydown', function (e) {
        if (e.key === 'Escape' && box.classList.contains('is-open')) close();
    });
})();
